package com.renthub.payment; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; @Entity @Table(name="RH_PAYMENTS") public class Payment{@Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="pay_seq") @SequenceGenerator(name="pay_seq",sequenceName="RH_PAYMENT_SEQ",allocationSize=1) private Long id; private Long bookingId; private Long userId; private BigDecimal amount; private String method; private String status; private String referenceNo; private LocalDateTime createdAt=LocalDateTime.now(); public Long getId(){return id;} public Long getBookingId(){return bookingId;} public void setBookingId(Long v){bookingId=v;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public String getMethod(){return method;} public void setMethod(String v){method=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getReferenceNo(){return referenceNo;} public void setReferenceNo(String v){referenceNo=v;} public LocalDateTime getCreatedAt(){return createdAt;}}
